INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (1, 'M0', 'M0: 固定倍数基线 (k=30)', '仅评测信号A', 'SQL', '经典 Boxleiter 固定常数：销量 = 评测数 × 30');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (2, 'M1', 'M1: 按年份分段文献值', '仅评测信号A', 'SQL', '按发售年代取文献中位数：<=2016取74, 17-18取60, 2019取51, >=2020取38');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (3, 'M2', 'M2: 对数线性回归 (含年代校准)', '仅评测信号A', 'Python Stats', '综合价格、好评率倒U形二次项、评测规模、游玩时长与中文占比的多元对数回归');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (4, 'M3', 'M3: 分位数回归 (中位数+80%区间)', '仅评测信号A', 'Python Stats', '基于 Pinball Loss 与残差分位数给出稳健中位数预测及 [P10, P90] 置信区间');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (5, 'M4', 'M4: 梯度提升/随机森林树模型', '仅评测信号A', 'Python ML', '非线性决策树集成学习，自动捕捉好评率倒U形与价格-时长交互效应');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (6, 'Signal_B', '信号B: 在线人数与人均时长推算', '仅在线信号B', 'Python Stats', '与评测无关：累计总游玩小时数 ÷ 校准后人均游玩时长（不受2019评测弹窗政策影响）');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (7, 'Fusion_AB', 'Fusion: 评测信号A + 在线信号B 加权融合', 'A+B双信号融合', 'Python ML', '对数空间双信号最优加权融合：突破单一评测信号的信息瓶颈');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (8, 'M4_Plus', 'M4+: 评测精修模型 (H1口径+H2分段+H5受众KNN)', '精修评测信号A+', 'Python ML', '纳入Key购买占比、首成就启动率、首发30天评测占比与K=5受众近邻残差校准');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (9, 'Signal_C', '信号C: 峰值在线 Peak CCU × 预购/长尾外推 (H3)', '独立峰值信号C', 'Python Stats', '基于GameDiscoverCo 2025定律：Peak CCU × (无预购14.1/有预购7.8) × 长尾留存比');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (10, 'Signal_D', '信号D: 社区关注 Followers -> 愿望单转化漏斗 (H4)', '独立社区信号D', 'Python Stats', '基于公开Followers × 12.37推算愿望单并结合好评率/价格转化率预测销量');
INSERT INTO `dim_estimation_method` (`method_id`, `method_code`, `method_name`, `signal_source`, `impl_tech`, `description`) VALUES (11, 'M6_Quad_Fusion', 'M6: 四信号自适应门控融合 (A+ / B+ / C / D)', '四信号动态融合', 'Python ML', '按首发期、促销期、小样本等状态自适应分配评测A+、时长B+、Peak CCU与Followers权重');
