INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step0_Baseline_M0', '基线 M0：固定倍数 (k=30)', 31.75, 23.85, 0.9086, 19.44, 55.56, 80.56, '传统 Boxleiter 常数，完全忽略年代与个体差异');
INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step1_Base_M2', '基准 M2：基础特征修正 + 2019年代校准', 28.89, 25.7, 0.9204, 22.22, 58.33, 83.33, '控制年份、价格、好评率倒U形与时长，触及传统单信号天花板');
INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step2_Add_H1', '+ 假设 H1：Key激活占比 + 历史最高折扣 + 首成就启动率', 25.46, 25.99, 0.9369, 27.78, 63.89, 91.67, '剔除慈善包、大促喜加一与买后未启动吃灰党导致的 k 畸变');
INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step3_Add_H2', '+ 假设 H2：首发30天原价期 vs 长尾促销期评测积分拆分', 23.37, 23.43, 0.9475, 27.78, 72.22, 91.67, '区分高评论率的首发核心粉丝与低评论率的长尾折扣买家');
INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step4_Add_H5', '+ 假设 H5：同受众特征空间 K=5 近邻残差校准 (M4+)', 21.63, 19.93, 0.9544, 27.78, 77.78, 94.44, '利用相似受众游戏(如魂类/肉鸽/模拟)的实测残差做局部校准');
INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step5_Add_SignalB', '+ 信号 B+：结合成就激活率修正的累计在线时长双信号融合', 15.19, 12.68, 0.9726, 44.44, 80.56, 100.0, '引入独立于评测的游玩总时长信号，抵消单信号观测方差');
INSERT INTO `ads_hypothesis_ablation` (`step_code`, `step_name`, `mape_pct`, `mdape_pct`, `r2_log`, `hit_rate_10pct`, `hit_rate_30pct`, `hit_rate_50pct`, `mechanism_desc`) VALUES ('Step6_Add_H3_H4_H6', '+ 假设 H3/H4/H6：融入 Peak CCU(信号C) + Followers(信号D) 四信号动态门控 (M6)', 13.65, 12.18, 0.9786, 41.67, 97.22, 100.0, '按首发/大促/小样本状态自适应融合四路独立信号，实现最高精度');
